<template>
  <AppPage title="运营订货单" subtitle="按国家选择普通商品与需求数量，核对后提交采购，跟进已拆和剩余需求。" :capability="error ? 'degraded' : 'connected'">
    <template #action><el-button v-if="canManage" type="primary" @click="openNew">新建运营订货单</el-button></template>
    <el-alert v-if="!canView" title="当前账号没有运营订货单查看权限。" type="warning" :closable="false" />
    <template v-else>
      <div class="filters"><el-input v-model="search" placeholder="订货单号 / 国家" clearable @keyup.enter="load" /><el-select v-model="status" clearable placeholder="全部状态"><el-option label="草稿" value="draft"/><el-option label="已提交" value="submitted"/><el-option label="已取消" value="cancelled"/></el-select><el-button @click="load">查询</el-button></div>
      <el-alert v-if="error" :title="error" type="error" :closable="false" />
      <div class="table-scroll"><el-table :data="rows" v-loading="loading" border empty-text="暂无运营订货单">
        <el-table-column prop="number" label="运营订货单号" min-width="180"/><el-table-column prop="country_name" label="国家" min-width="130"/><el-table-column label="来源" width="130"><template #default="{row}">{{sourceLabel(row.source_kind)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{statusLabel(row.status)}}</template></el-table-column><el-table-column prop="total_quantity" label="总数量" width="110" align="right"/><el-table-column prop="order_date" label="日期" width="120"/><el-table-column label="操作" width="180" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openDetail(row)">查看</el-button><el-button v-if="canManage && row.status==='draft'" link @click="openDetail(row)">编辑</el-button></template></el-table-column>
      </el-table></div><el-pagination class="pagination" layout="total, prev, pager, next" :total="total" :current-page="page" :page-size="20" @current-change="changePage"/>
    </template>
    <el-drawer v-model="drawer" :title="selected ? `${selected.number} · ${statusLabel(selected.status)}` : '新建运营订货单'" size="min(1100px, 96vw)">
      <div v-if="drawer" class="drawer-content">
        <el-alert v-if="selected?.status==='submitted'" title="已提交的订货单及数量不可修改；采购团队可按剩余数量拆分。" type="info" :closable="false"/>
        <div class="form-grid"><el-form-item label="国家 *"><el-select v-model="form.country_id" filterable remote :remote-method="s=>loadOptions('countries',s)" :disabled="!editable" placeholder="搜索国家"><el-option v-for="c in countries" :key="c.id" :label="`${c.name} (${c.country_code || c.code})`" :value="c.id"/></el-select></el-form-item>
          <el-form-item label="来源 *"><el-select v-model="form.source_kind" :disabled="!editable"><el-option label="新品手工订货" value="new_goods"/><el-option label="常规补货建议" value="cycle"/><el-option label="季节／活动补货建议" value="season"/></el-select></el-form-item><el-form-item label="订货日期"><el-date-picker v-model="form.order_date" value-format="YYYY-MM-DD" type="date" :disabled="!editable"/></el-form-item></div>
        <div class="form-grid"><el-form-item label="活动 / 季节"><el-input v-model="form.campaign" maxlength="120" :disabled="!editable" placeholder="如：圣诞备货"/></el-form-item><el-form-item label="计划版本"><el-input v-model="form.plan_revision" maxlength="40" :disabled="!editable" placeholder="如：V1"/></el-form-item><el-form-item label="需求开始"><el-date-picker v-model="form.demand_start" value-format="YYYY-MM-DD" type="date" :disabled="!editable"/></el-form-item><el-form-item label="需求结束"><el-date-picker v-model="form.demand_end" value-format="YYYY-MM-DD" type="date" :disabled="!editable"/></el-form-item></div>
        <el-form-item label="备注"><el-input v-model="form.notes" type="textarea" :disabled="!editable"/></el-form-item>
        <section v-if="form.source_kind!=='new_goods' && (editable || preview)" class="preview-box"><h3>统一补货建议</h3><p>来源清单与已选SKU复核使用相同的国家补货策略和销量口径。草稿保存后保留当次计算快照。</p><el-button v-if="editable" :loading="previewing" :disabled="!form.country_id || !form.lines.length" @click="makePreview">重新核对已选商品建议</el-button><el-alert v-if="editable && form.lines.some(l=>l.sku_id && form.lines.filter(x=>x.sku_id===l.sku_id).length>1)" title="SKU 不能重复，请移除重复行。" type="error" :closable="false"/><el-alert v-if="preview" class="review" title="该结果是待人工复核的建议，不会直接生成实际订单。重新计算时，若建议数量与人工填写数量不同，将先提示并由你决定是否应用。" type="warning" :closable="false"/><p v-if="preview" class="muted">{{preview.formula}}　·　生成时间：{{preview.generated_at}}</p><p v-if="preview" class="muted">库存快照：{{sourceSnapshotIds.join('、')||'无'}}　·　销量同步批次：{{sourceRunIds.join('、')||'无'}}</p></section>
        <OperatingReferenceV2 v-if="editable && form.source_kind!=='new_goods'" :parameters="referenceParameters" :disabled="busy || !form.country_id" audience="operator" :issue-label="issueLabel" @source-change="form.source_kind=$event" @strategy="useReferenceStrategy" @select="applyReference"/>
        <div class="section-heading"><h3>订货 SKU</h3><el-button v-if="editable" @click="addLine">添加 SKU</el-button></div>
        <div class="table-scroll"><el-table :data="form.lines" border empty-text="周期/季节模式请先生成国家参考清单并勾选；新品可手工添加 SKU"><el-table-column type="index" label="#" width="50"/><el-table-column label="商品图片" width="110"><template #default="{row}"><OperatingProductImageV2 v-if="row.sku_id" :sku-id="row.sku_id" :source="row.product_details?.image_url || ''" /></template></el-table-column><el-table-column label="SKU / 商品" min-width="250"><template #default="{row}"><el-select v-if="editable" v-model="row.sku_id" filterable remote :remote-method="s=>loadOptions('skus',s)" placeholder="搜索新旧 SKU / 商品" aria-label="运营订货 SKU" @visible-change="open=>open && loadOptions('skus','')" @change="selectSku(row)"><el-option v-for="item in skus" :key="item.id" :label="skuLabel(item)" :value="item.id"/></el-select><DocumentSkuV2 v-if="row.sku_id" :sku="row.sku" :legacy-sku-code="row.legacy_sku_code"/><small v-if="row.product_name" class="line-product-name">{{row.product_name}}</small></template></el-table-column><el-table-column label="订货数量" width="160"><template #default="{row}"><el-input-number v-if="editable" v-model="row.quantity" :min="1" :precision="0" :controls="false"/><span v-else>{{row.quantity}}</span></template></el-table-column><el-table-column v-if="selected && selected.status!=='draft'" label="已拆数量" width="110"><template #default="{row}">{{row.allocated_quantity ?? 0}}</template></el-table-column><el-table-column v-if="selected && selected.status!=='draft'" label="剩余需求" width="110"><template #default="{row}">{{row.remaining_quantity ?? row.quantity}}</template></el-table-column><el-table-column v-if="preview" label="建议依据" min-width="320"><template #default="{row}"><OperatingDemandV2 :evidence="row"/><small>可用库存 {{row.available_stock ?? '—'}} · 按期到货 {{row.in_transit_stock ?? '—'}} · 开放需求 {{row.pipeline?.open_operating_demand ?? '—'}} · 建议 {{row.suggested_quantity ?? '—'}}</small><small v-if="row.sources?.length">来源：{{row.sources.join('；')}}</small><small v-if="row.issues?.length" class="issue">问题：{{row.issues.map(issueLabel).join('；')}}</small></template></el-table-column><el-table-column v-if="editable" label="操作" width="80"><template #default="{ $index }"><el-button link type="danger" @click="form.lines.splice($index,1)">移除</el-button></template></el-table-column></el-table></div>
        <el-alert v-if="formError" :title="formError" type="error" :closable="false"/><p class="muted">当前 {{form.lines.length}} 个 SKU · {{totalQuantity}} 件{{preview ? ` · 建议已生成，待核对` : ''}}</p>
      </div>
      <template #footer><div class="actions"><el-button @click="drawer=false">关闭</el-button><el-button v-if="editable" type="primary" :loading="busy" @click="save">保存草稿</el-button><el-button v-if="canManage && selected?.status==='draft'" :disabled="busy || dirty" type="success" @click="transition('submit')">提交至采购</el-button><el-button v-if="canManage && ['draft','submitted'].includes(selected?.status)" :disabled="busy || dirty" type="danger" @click="transition('cancel')">取消订单</el-button></div></template>
    </el-drawer>
  </AppPage>
</template>

<script setup>
import { computed, defineAsyncComponent, nextTick, onMounted, reactive, ref, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import AppPage from '../../components/AppPage.vue';
import DocumentSkuV2 from '../../components/supply-chain/DocumentSkuV2.vue';
import OperatingProductImageV2 from '../../components/supply-chain/OperatingProductImageV2.vue';
import OperatingDemandV2 from '../../components/supply-chain/OperatingDemandV2.vue';
import { useAuthStore } from '../../stores/auth';
import * as api from '../../api/operatingOrdersV2';
import { cockpitActorKey, consumeCockpitDraft } from '../../utils/cockpitDraft';
const OperatingReferenceV2=defineAsyncComponent(()=>import('../../components/supply-chain/OperatingReferenceV2.vue'));
const auth=useAuthStore(), canView=computed(()=>!auth.authorizationStale && auth.hasPermission('sales_management.operating_orders.view')), canManage=computed(()=>canView.value && auth.hasPermission('sales_management.operating_orders.manage'));
const rows=ref([]),total=ref(0),page=ref(1),search=ref(''),status=ref(''),loading=ref(false),busy=ref(false),error=ref(''),drawer=ref(false),selected=ref(null),formError=ref(''),countries=ref([]),skus=ref([]),preview=ref(null),previewing=ref(false);
const businessDate=(date)=>{const parts=new Intl.DateTimeFormat('en',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);return `${parts.find(p=>p.type==='year').value}-${parts.find(p=>p.type==='month').value}-${parts.find(p=>p.type==='day').value}`}, businessToday=()=>businessDate(new Date()), blank=()=>({country_id:null,source_kind:'new_goods',notes:'',campaign:'',plan_revision:'',demand_start:null,demand_end:null,order_date:businessToday(),lines:[]}), form=reactive(blank()), previewForm=reactive({strategy_id:null,algorithm_version:'weighted_days_v1',sales_end:'',activity_start:null,activity_end:null,activity_factor:1});
const editable=computed(()=>canManage.value && (!selected.value || selected.value.status==='draft')), totalQuantity=computed(()=>form.lines.reduce((sum,l)=>sum+Number(l.quantity||0),0)), statusLabel=s=>({draft:'草稿',submitted:'已提交',cancelled:'已取消'}[s]||s), sourceLabel=s=>({new_goods:'新品手工',cycle:'常规补货建议',season:'季节／活动补货建议'}[s]||s);
const payload=()=>({country_id:form.country_id,source_kind:form.source_kind,notes:form.notes,campaign:form.campaign,plan_revision:form.plan_revision,demand_start:form.demand_start||null,demand_end:form.demand_end||null,order_date:form.order_date,lines:form.lines.map(l=>({sku_id:l.sku_id,quantity:Number(l.quantity)}))}), baseline=ref(''), dirty=computed(()=>JSON.stringify(payload())!==baseline.value);
const referenceParameters=computed(()=>({country_id:form.country_id,source_kind:form.source_kind,...previewForm,...(selected.value?.status==='draft'?{exclude_operating_order_id:selected.value.id}:{})}));
let contextGeneration=0;
const contextKey=()=>JSON.stringify([cockpitActorKey(auth.currentUser),auth.authorizationStale]);
const previewInput=()=>JSON.stringify({context:contextKey(),source_kind:form.source_kind,country_id:form.country_id,sku_ids:form.lines.map(l=>l.sku_id),...previewForm,...(selected.value?.status==='draft'?{exclude_operating_order_id:selected.value.id}:{})});
const suppressPreviewInvalidation=ref(false);
watch(previewInput,()=>{if(suppressPreviewInvalidation.value)return;preview.value=null; pending.delete('preview');});
const sourceSnapshotIds=computed(()=>[...new Set((preview.value?.lines||[]).flatMap(line=>line.source_snapshot_ids||[]))]), sourceRunIds=computed(()=>[...new Set((preview.value?.lines||[]).flatMap(line=>line.source_run_ids||[]))]);
const failed=r=>r?.data?.detail||r?.message||'请求失败，请重试。', pending=new Map(), run=async(slot,data,fn)=>{if(!canManage.value||busy.value)return null;const context=contextGeneration,fp=JSON.stringify(data);let p=pending.get(slot);if(!p||p.fp!==fp){p={fp,key:api.createIdempotencyKey()};pending.set(slot,p)}busy.value=true;try{const r=await fn(p.key);if(context!==contextGeneration)return null;if(r?.success){pending.delete(slot);return r.data}formError.value=`${failed(r)}${!r?.http_status||r.http_status>=500?' 结果未确认，可用相同内容安全重试。':''}`;if(r?.http_status&&r.http_status<500)pending.delete(slot);return null}catch(e){if(context!==contextGeneration)return null;formError.value=`${e.message||'网络异常'}，结果未确认，可用相同内容安全重试。`;return null}finally{if(context===contextGeneration)busy.value=false}};
watch(contextKey,()=>{contextGeneration++;consumeCockpitDraft(auth.currentUser);pending.clear();busy.value=false;loading.value=false;previewing.value=false;drawer.value=false;selected.value=null;preview.value=null;rows.value=[];total.value=0;countries.value=[];skus.value=[];Object.assign(form,blank());error.value='';formError.value='账号或组织已切换，请重新选择商品。';},{flush:'sync'});
async function load(){if(!canView.value)return;const context=contextGeneration;loading.value=true;error.value='';try{const r=await api.fetchOperatingOrders({search:search.value.trim(),status:status.value,limit:20,offset:(page.value-1)*20});if(context!==contextGeneration)return;if(!r?.success){error.value=failed(r);return}rows.value=Array.isArray(r.data)?r.data:r.data?.results||[];total.value=Number(r.count??r.data?.count??0)}finally{if(context===contextGeneration)loading.value=false}}
const skuLabel=item=>`${item.sku_code}${item.legacy_sku_code ? ` · 旧 ${item.legacy_sku_code}` : ''} · ${item.product_name}`;
function changePage(v){page.value=v;load()} async function loadOptions(kind,search=''){const context=contextGeneration;const r=await api.fetchOperatingOptions({kind,search,limit:100,offset:0});if(context!==contextGeneration)return;if(!r?.success){formError.value=failed(r);return}if(kind==='countries')countries.value=r.data||[];else {const found=r.data||[],ids=new Set(found.map(item=>item.id));skus.value=[...found,...form.lines.filter(line=>line.sku_id&&!ids.has(line.sku_id)).map(line=>({id:line.sku_id,sku_code:line.sku,legacy_sku_code:line.legacy_sku_code,product_name:line.product_name,product_details:line.product_details}))]}}
function openNew(){if(!canManage.value)return;selected.value=null;Object.assign(form,blank());preview.value=null;formError.value='';baseline.value=JSON.stringify(payload());drawer.value=true;loadOptions('countries','')}
async function openDetail(row){const context=contextGeneration;const r=await api.fetchOperatingOrder(row.id);if(context!==contextGeneration)return;if(!r?.success){ElMessage.error(failed(r));return}const snapshot=r.data.calculation_snapshot?.formula?r.data.calculation_snapshot:null,calculationLines=new Map((snapshot?.lines||[]).map(line=>[line.sku_id,line]));selected.value=r.data;suppressPreviewInvalidation.value=true;Object.assign(form,{country_id:r.data.country_id,source_kind:r.data.source_kind,notes:r.data.notes||'',campaign:r.data.campaign||'',plan_revision:r.data.plan_revision||'',demand_start:r.data.demand_start||null,demand_end:r.data.demand_end||null,order_date:r.data.order_date||'',lines:(r.data.lines||[]).map(l=>({...calculationLines.get(l.sku_id),sku_id:l.sku_id,sku:l.sku,legacy_sku_code:l.legacy_sku_code||'',product_name:l.product_name,product_details:l.product_details||{},quantity:Number(l.quantity),allocated_quantity:l.allocated_quantity,remaining_quantity:l.remaining_quantity}))});if(snapshot?.parameters)Object.assign(previewForm,{strategy_id:snapshot.parameters.strategy_id||null,algorithm_version:snapshot.parameters.algorithm_version||'weighted_days_v1',sales_end:snapshot.parameters.sales_end||snapshot.generated_at?.slice(0,10)||'',activity_start:snapshot.parameters.activity_start||null,activity_end:snapshot.parameters.activity_end||null,activity_factor:Number(snapshot.parameters.activity_factor||1)});baseline.value=JSON.stringify(payload());preview.value=snapshot;formError.value='';drawer.value=true;await nextTick();suppressPreviewInvalidation.value=false;if(context!==contextGeneration)return;loadOptions('countries','');loadOptions('skus','')}
function addLine(){if(editable.value)form.lines.push({sku_id:null,sku:'',legacy_sku_code:'',product_name:'',product_details:{},quantity:1})} function selectSku(line){const o=skus.value.find(s=>s.id===line.sku_id);if(o)Object.assign(line,{sku:o.sku_code,legacy_sku_code:o.legacy_sku_code||'',product_name:o.product_name,product_details:o.product_details||{}})}
const issueLabels={bundle_composition_unverified:'组合商品历史构成缺失或无效，需求待核对',country_sales_coverage_unproven:'国家销量采集完整性待复核',platform_sales_exceeds_country_total:'平台需求超过国家汇总，请重新核对',collection_coverage_unproven:'采集完整性待复核',refunds_not_deducted:'退款单独列示，不扣减销量',missing_inventory_snapshot:'缺少库存快照',no_sales_facts:'缺少销量事实',unmapped_inventory:'存在未映射库存',unmapped_sales_lines:'存在未映射销量明细',inventory_source_incomplete:'库存来源不完整',stale_inventory_snapshot:'库存快照已过期',available_quantity_unverified:'库存数量来源字段待核对',ambiguous_inventory_aliases:'新旧SKU来源库存存在歧义',supply_summary_not_authorized:'缺少供应数量汇总权限',warehouse_supply_scope_incomplete:'仓库范围下供应量不完整',unassigned_warehouse_supply:'供应量未分配目的仓',unknown_eta:'部分供应无预计到仓日期，未计入按期到货',overdue_eta:'预计到仓日期已过期',wms_receipt_overlap_unresolved:'WMS已收货与在途可能重复，请对账',wms_allocation_requires_review:'WMS关联待核对',local_receipt_quantity_difference:'本地实收与发货数量存在差异',no_authorized_sales_store:'无可读取的销售店铺',unfinished_store_day:'销售日期尚未完整结束',invalid_store_timezone:'店铺时区无效'};
function issueLabel(code){return issueLabels[code]||code}
function validatePreview(requireSkus=true){if(!form.country_id){formError.value='请选择国家。';return false}if(!previewForm.strategy_id){formError.value='请先在供应链设置保存该国家的补货策略。';return false}if(form.source_kind==='season' && (!previewForm.activity_start||!previewForm.activity_end||previewForm.activity_start>previewForm.activity_end)){formError.value='活动模式需要填写有效的活动起止日期。';return false}if(!Number.isFinite(Number(previewForm.activity_factor))||Number(previewForm.activity_factor)<0.01||Number(previewForm.activity_factor)>20){formError.value='活动需求系数须为0.01到20。';return false}if(!requireSkus)return true;const ids=form.lines.map(l=>l.sku_id);if(ids.length>100){formError.value='建议订货每次最多100个商品，请分单处理。';return false}if(!ids.length||ids.some(id=>!id)||new Set(ids).size!==ids.length){formError.value='请填写SKU，且不可重复。';return false}return true}
function useReferenceStrategy(strategy){if(strategy?.configured===false)return;Object.assign(previewForm,{strategy_id:strategy?.id||null,sales_end:strategy?.sales_end||previewForm.sales_end});}
async function applyReference(selection){
  if(!editable.value||busy.value)return;
  const rows=selection?.rows||[]; const parameters=selection?.parameters||{};
  Object.assign(previewForm,{strategy_id:parameters.strategy_id||null,algorithm_version:'weighted_days_v1',sales_end:parameters.sales_end||'',activity_start:parameters.activity_start||null,activity_end:parameters.activity_end||null,activity_factor:Number(parameters.activity_factor||1)});
  if(parameters.source_kind&&['cycle','season'].includes(parameters.source_kind))form.source_kind=parameters.source_kind;
  const byId=new Map(form.lines.filter(line=>line.sku_id).map(line=>[line.sku_id,line]));
  for(const row of rows){if(!byId.has(row.sku_id))byId.set(row.sku_id,{...row,quantity:Number(row.suggested_quantity)});}
  if(byId.size>100){formError.value='合并已选商品后超过100个，请减少商品或分单。';return;}
  const options=new Map(skus.value.map(item=>[item.id,item]));
  for(const row of rows)options.set(row.sku_id,{id:row.sku_id,sku_code:row.sku_code||row.sku,legacy_sku_code:row.legacy_sku_code||'',product_name:row.product_name||'',product_details:row.product_details||{}});
  skus.value=[...options.values()];
  form.lines=[...byId.values()];
  await nextTick();await makePreview();
}
async function makePreview(){formError.value='';if(!editable.value||!validatePreview())return;const data={country_id:form.country_id,sku_ids:form.lines.map(l=>l.sku_id),source_kind:form.source_kind,strategy_id:previewForm.strategy_id,algorithm_version:previewForm.algorithm_version,...(previewForm.sales_end?{sales_end:previewForm.sales_end}:{}),activity_start:previewForm.activity_start,activity_end:previewForm.activity_end,activity_factor:previewForm.activity_factor,...(selected.value?.status==='draft'?{exclude_operating_order_id:selected.value.id}:{})};const fingerprint=previewInput(),context=contextGeneration;previewing.value=true;try{const out=await run('preview',data,key=>api.previewOperatingOrder(data,key));if(!out||fingerprint!==previewInput()||context!==contextGeneration)return;preview.value=out;const byId=new Map(out.lines.map(l=>[l.sku_id,l]));const changes=form.lines.map(line=>({line,suggested:Number(byId.get(line.sku_id)?.suggested_quantity)})).filter(item=>Number.isInteger(item.suggested)&&item.suggested>0&&item.suggested!==Number(item.line.quantity));let apply=false;if(changes.length){try{await ElMessageBox.confirm(`重新计算后有 ${changes.length} 行建议数量变化。是否将系统建议应用到订货数量？选择取消会保留你当前填写的数量。`,'确认应用建议',{confirmButtonText:'应用建议数量',cancelButtonText:'保留当前数量',type:'warning'});apply=true}catch{apply=false}}if(context!==contextGeneration||fingerprint!==previewInput())return;form.lines=form.lines.map(line=>{const evidence=byId.get(line.sku_id)||{};return {...line,...evidence,quantity:apply&&Number(evidence.suggested_quantity)>0?Number(evidence.suggested_quantity):line.quantity}});}finally{if(context===contextGeneration)previewing.value=false}}
async function save(){formError.value='';if(!editable.value)return;if(Boolean(form.demand_start)!==Boolean(form.demand_end)||(form.demand_start&&form.demand_end&&form.demand_start>form.demand_end)){formError.value='请同时填写正确的需求起止日期。';return;}if(!form.country_id||!form.lines.length||form.lines.some(l=>!l.sku_id||!Number.isInteger(Number(l.quantity))||Number(l.quantity)<=0)){formError.value='请选择国家，并为每个 SKU 填写大于 0 的整数数量。';return}if(form.source_kind!=='new_goods'&&(!preview.value||preview.value.parameters?.country_id!==form.country_id||JSON.stringify(preview.value.parameters?.sku_ids)!==JSON.stringify(form.lines.map(l=>l.sku_id)))){formError.value='请先为当前国家和 SKU 生成建议预览。';return}if(form.source_kind!=='new_goods'&&preview.value.lines.some(l=>!Number.isInteger(Number(l.suggested_quantity))||Number(l.suggested_quantity)<=0)){formError.value='请移除建议缺失或为 0 的 SKU 行后再保存。';return}const data={...payload(),...(preview?.value?.preview_token?{preview_token:preview.value.preview_token}:{}),...(selected.value?{expected_version:selected.value.version}:{})};const out=await run(`save-${selected.value?.id||'new'}`,data,key=>selected.value?api.updateOperatingOrder(selected.value.id,data,key):api.createOperatingOrder(data,key));if(out){selected.value=out;baseline.value=JSON.stringify(payload());preview.value=out.calculation_snapshot?.formula?out.calculation_snapshot:null;await load();ElMessage.success('运营订货草稿已保存。')}}
async function transition(action){if(!canManage.value||!selected.value||dirty.value)return;if(action==='submit'&&selected.value.status!=='draft')return;if(action==='cancel'&&!['draft','submitted'].includes(selected.value.status))return;const data={expected_version:selected.value.version},fn=action==='submit'?api.submitOperatingOrder:api.cancelOperatingOrder;const out=await run(`${action}-${selected.value.id}`,data,key=>fn(selected.value.id,data,key));if(out){selected.value=out;baseline.value=JSON.stringify(payload());await load()}}
async function receiveCockpitDraft(){
  const context=contextGeneration,incoming=consumeCockpitDraft(auth.currentUser);
  if(!incoming||!canManage.value)return;
  openNew();
  Object.assign(form,{country_id:incoming.parameters.country_id,source_kind:incoming.parameters.source_kind,lines:incoming.lines});
  skus.value=incoming.lines.map(line=>({id:line.sku_id,sku_code:line.sku,legacy_sku_code:line.legacy_sku_code,product_name:line.product_name}));
  Object.assign(previewForm,{strategy_id:incoming.parameters.strategy_id||null,algorithm_version:'weighted_days_v1',sales_end:incoming.parameters.sales_end||'',activity_start:incoming.parameters.activity_start||null,activity_end:incoming.parameters.activity_end||null,activity_factor:Number(incoming.parameters.activity_factor||1)});
  baseline.value=JSON.stringify(blank());
  await nextTick();
  if(context!==contextGeneration)return;
  await makePreview();
  if(context!==contextGeneration)return;
  if(!preview.value)formError.value=formError.value||'已带入商品，建议复核未完成；请重新计算后再保存。';
}
onMounted(()=>{load();receiveCockpitDraft();});
</script>
