.line-product-name{display:block;margin-top:6px;overflow-wrap:anywhere}.filters,.actions,.section-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.filters{margin:12px 0 18px}.filters>.el-input{width:min(340px,100%)}.filters>.el-select{width:170px}.table-scroll{overflow-x:auto;width:100%}.pagination{margin-top:16px}.drawer-content{padding-bottom:24px}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 16px}.form-grid :deep(.el-select),.form-grid :deep(.el-date-editor){width:100%}.section-heading{justify-content:space-between;margin:20px 0 12px}.section-heading h3,.preview-box h3{margin:0;font-size:16px}.preview-box{padding:16px;margin:18px 0;background:#f8fafc;border-radius:8px}.preview-box .review{margin-top:14px}.muted,small{color:#64748b}.issue{display:block;color:#b42318}.actions{justify-content:flex-end}@media(max-width:680px){.form-grid{grid-template-columns:1fr}.filters>.el-input,.filters>.el-select{width:100%}.actions{justify-content:flex-start}}
